import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppState {
  SETUP = 'SETUP',
  COUNTDOWN = 'COUNTDOWN',
  ALERT = 'ALERT',
  RELAXING = 'RELAXING'
}

export interface IntervalOption {
  label: string;
  seconds: number;
}

export const ACTIVITY_INTERVALS: IntervalOption[] = [
  { label: '6 seconds (Test)', seconds: 6 },
  { label: '0.5 hour', seconds: 1800 },
  { label: '1 hour', seconds: 3600 },
  { label: '1.5 hours', seconds: 5400 },
  { label: '2 hours', seconds: 7200 },
  { label: '2.5 hours', seconds: 9000 },
  { label: '3 hours', seconds: 10800 },
  { label: '3.5 hours', seconds: 12600 },
  { label: '4 hours', seconds: 14400 }
];

export const DELAY_INTERVALS: IntervalOption[] = [
  { label: '5 minutes', seconds: 300 },
  { label: '10 minutes', seconds: 600 },
  { label: '15 minutes', seconds: 900 },
  { label: '30 minutes', seconds: 1800 }
];

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { AppState, ACTIVITY_INTERVALS, DELAY_INTERVALS } from './types';
import SetupScreen from './components/SetupScreen';
import RunningScreen from './components/RunningScreen';
import AlertScreen from './components/AlertScreen';
import RelaxScreen from './components/RelaxScreen';

const App: React.FC = () => {
  const [currentScreen, setCurrentScreen] = useState<AppState>(AppState.SETUP);
  const [timeLeft, setTimeLeft] = useState<number>(0);
  const [selectedInterval, setSelectedInterval] = useState<number>(ACTIVITY_INTERVALS[0].seconds);
  const [selectedDelay, setSelectedDelay] = useState<number>(DELAY_INTERVALS[0].seconds);

  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Clear timer on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  const startTimer = useCallback((seconds: number) => {
    setTimeLeft(seconds);
    setCurrentScreen(AppState.COUNTDOWN);

    if (timerRef.current) clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          if (timerRef.current) clearInterval(timerRef.current);
          setCurrentScreen(AppState.ALERT);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  }, []);

  const handleStartActivity = () => {
    startTimer(selectedInterval);
  };

  const handleRelaxNow = () => {
    setCurrentScreen(AppState.RELAXING);
  };

  const handleDelayRelax = () => {
    startTimer(selectedDelay);
  };

  const handleCloseApp = () => {
    // In a browser, we can't literally close the tab easily, 
    // but we can reset the state to simulate "closing" the active session
    setCurrentScreen(AppState.SETUP);
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const handleRelaxFinished = () => {
    // After relaxation, go back to setup or restart the main activity timer?
    // Requirement implies returning to a state where we can start again.
    setCurrentScreen(AppState.SETUP);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-indigo-950 via-slate-900 to-emerald-950">
      <div className="w-full max-w-lg bg-white/10 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/20 overflow-hidden relative">
        {/* Custom Window Controls Decorator */}
        <div className="flex items-center gap-2 p-4 bg-white/5 border-b border-white/10">
          <div className="w-3 h-3 rounded-full bg-red-500/80 cursor-pointer hover:bg-red-400" onClick={handleCloseApp}></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500/80"></div>
          <div className="w-3 h-3 rounded-full bg-green-500/80"></div>
          <span className="ml-2 text-xs font-mono text-white/40 uppercase tracking-widest">SlowDown Hare v1.0</span>
        </div>

        <div className="p-8">
          {currentScreen === AppState.SETUP && (
            <SetupScreen 
              onStart={handleStartActivity} 
              onIntervalChange={setSelectedInterval}
              intervals={ACTIVITY_INTERVALS}
            />
          )}

          {currentScreen === AppState.COUNTDOWN && (
            <RunningScreen 
              timeLeft={timeLeft} 
              onCancel={handleCloseApp} 
            />
          )}

          {currentScreen === AppState.ALERT && (
            <AlertScreen 
              onRelaxNow={handleRelaxNow}
              onDelayRelax={handleDelayRelax}
              onClose={handleCloseApp}
              onDelayChange={setSelectedDelay}
              delayIntervals={DELAY_INTERVALS}
            />
          )}
        </div>
      </div>

      {currentScreen === AppState.RELAXING && (
        <RelaxScreen onBack={handleRelaxFinished} />
      )}
    </div>
  );
};

export default App;

